buggy.yn_3_1e-105_error_message:
import scipy.special as sc

name = "with sc.errstate(all='raise'): sc.yn(3, 1e-105)"
value = 0  # no error raised

try:
    with sc.errstate(all="raise"):
        sc.yn(3, 1e-105)
except sc.SpecialFunctionError as exc:
    msg = str(exc).lower()
    if "overflow" in msg:
        value = 1
    elif "underflow" in msg:
        value = 2
    else:
        value = 3
except Exception:
    value = -1

probe(name, value)

